import html


def customer_retention_html(api_version):
    page = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>VaultLink Storage & Retention</title>
  <style>
    :root{--bg:#0c1013;--band:#12181d;--surface:#182129;--field:#080b0e;--line:#35444f;--text:#f5f7f8;--muted:#a8b6bf;--green:#62e58d;--blue:#5ec5ed;--yellow:#ffd166;--red:#ff7d75}*{box-sizing:border-box}html{background:var(--bg);color:var(--text);font-family:Segoe UI,Arial,sans-serif;letter-spacing:0}body{margin:0;min-width:0;background:var(--bg)}button,select{font:inherit;letter-spacing:0}header{border-bottom:1px solid var(--line);background:var(--band)}header>div,main,footer>div{width:min(1180px,calc(100% - 32px));margin:auto}header>div{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:64px}.brand{font-size:1rem;font-weight:800}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{padding:8px 9px;border:1px solid var(--line);border-radius:5px;color:var(--text);font-size:.73rem;font-weight:800;text-decoration:none}main{padding:34px 0 48px}h1{margin:0;font-size:2rem;line-height:1.1}h2{margin:0;font-size:1.25rem}h3{margin:0;font-size:1rem}p{color:var(--muted);line-height:1.5}.lead{max-width:880px;margin:9px 0 0}.privacy{margin:18px 0;padding:14px 16px;border-left:4px solid var(--green);background:var(--band);color:var(--muted);line-height:1.5}.controls{display:grid;grid-template-columns:minmax(210px,1fr) repeat(6,auto);gap:9px;align-items:end;padding:14px;border:1px solid var(--line);background:var(--band)}label,.eyebrow{display:block;margin-bottom:6px;color:var(--yellow);font-size:.69rem;font-weight:800;text-transform:uppercase}select,button{min-height:40px;border:1px solid var(--line);border-radius:5px}select{width:100%;padding:0 11px;background:var(--field);color:var(--text)}button{padding:0 12px;background:#27343e;color:var(--text);font-size:.75rem;font-weight:800;cursor:pointer}button.primary{background:var(--green);color:#041008;border-color:var(--green)}button.export{background:var(--yellow);color:#151000;border-color:var(--yellow)}button:disabled,select:disabled{cursor:not-allowed;opacity:.45}.status{min-height:32px;padding:9px 0;color:var(--muted)}.status.good{color:var(--green)}.status.bad{color:var(--red)}.metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));margin:4px 0 24px;border:1px solid var(--line)}.metric{min-width:0;padding:14px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric span{display:block;color:var(--muted);font-size:.68rem;font-weight:700;text-transform:uppercase}.metric strong{display:block;margin-top:6px;overflow-wrap:anywhere;font-size:1rem}.section{margin-top:26px;padding-top:22px;border-top:1px solid var(--line)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:13px}.section-head p{max-width:680px;margin:0;text-align:right}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.area,.practice,.flow article,.boundary{min-width:0;padding:16px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.area{border-left:4px solid var(--blue)}.area h3,.practice h3{margin-top:4px}.policy{color:var(--blue);font-size:.68rem;font-weight:800;text-transform:uppercase}.facts{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.fact{padding:10px;border-top:1px solid var(--line)}.fact strong{display:block;margin-bottom:4px;color:var(--yellow);font-size:.68rem;text-transform:uppercase}.fact span{display:block;color:var(--muted);font-size:.82rem;line-height:1.4;overflow-wrap:anywhere}.practice{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px}.practice.reviewed{border-color:var(--green)}.practice input{width:19px;height:19px;margin:2px 0 0;accent-color:var(--green)}.flow,.boundaries{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.flow article{border-top:3px solid var(--green)}.boundary{border-top:3px solid var(--yellow)}.flow p,.boundary p{margin:7px 0 0;font-size:.88rem}footer{border-top:1px solid var(--line);background:var(--band)}footer>div{padding:20px 0;color:var(--muted);font-size:.82rem;line-height:1.45}@media(max-width:980px){.controls{grid-template-columns:repeat(3,minmax(0,1fr))}.controls>div{grid-column:1/-1}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.metric:nth-child(3){border-right:0}.cards{grid-template-columns:1fr}}@media(max-width:620px){header>div{align-items:flex-start;flex-direction:column;padding:14px 0}main{padding-top:24px}h1{font-size:1.65rem}.controls{grid-template-columns:1fr}.controls button{width:100%}.metrics{grid-template-columns:1fr}.metric{border-right:0;border-bottom:1px solid var(--line)}.metric:last-child{border-bottom:0}.section-head{align-items:flex-start;flex-direction:column}.section-head p{text-align:left}.facts,.flow,.boundaries{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header><div><div class="brand">VaultLink Storage & Retention</div><nav><a href="/workspace">WORKSPACE</a><a href="/data-control">DATA</a><a href="/recovery-kit">KIT</a><a href="/backup-verification">BACKUPS</a><a href="/diagnostics">DIAGNOSTICS</a><a href="/trust">TRUST</a><a href="/privacy">PRIVACY</a><a href="/status">STATUS</a></nav></div></header>
  <main>
    <h1>Keep what protects recovery</h1>
    <p class="lead">Review fixed retention areas and safe cleanup practices without sending a file inventory, path, customer record, local result, or cleanup command.</p>
    <div class="privacy">This public workspace cannot inspect or clean a PC. Practice progress exists only in the current tab and disappears on reload. Real cleanup remains an explicit, typed-confirmation desktop action limited to VaultLink's temporary workspace.</div>
    <div class="controls">
      <div><label for="policy">Retention policy</label><select id="policy" disabled></select></div>
      <button id="reset" type="button" disabled>RESET</button><button id="next" class="primary" type="button" disabled>REVIEW NEXT</button><button id="visible" type="button" disabled>REVIEW ALL</button><button id="copy" type="button" disabled>COPY PLAN</button><button id="print" type="button" disabled>PRINT</button><button id="export" class="export" type="button" disabled>EXPORT SAFE JSON</button>
    </div>
    <div id="status" class="status" role="status" aria-live="polite">Loading the fixed retention guide...</div>
    <div id="workspace" hidden>
      <div id="metrics" class="metrics"></div>
      <section class="section"><div class="section-head"><div><div class="eyebrow">FIXED STORAGE MAP</div><h2>Retention areas</h2></div><p>The browser shows policy only. It receives no local presence, age, count, size, or cleanup result.</p></div><div id="areas" class="cards"></div></section>
      <section class="section"><div class="section-head"><div><div class="eyebrow">CUSTOMER REVIEW</div><h2>Safe retention practices</h2></div><p>Checking a practice records progress only in this page's memory.</p></div><div id="practices" class="cards"></div></section>
      <section class="section"><div class="section-head"><div><div class="eyebrow">CLEANUP FLOW</div><h2>How desktop cleanup is bounded</h2></div><p>No cleanup endpoint exists on this API.</p></div><div id="flow" class="flow"></div></section>
      <section class="section"><div class="section-head"><h2>Privacy boundaries</h2><p>These boundaries are fixed server text, not claims about a customer PC.</p></div><div id="boundaries" class="boundaries"></div></section>
      <section class="section"><div class="section-head"><h2>Limitations</h2><p>Retention review supports good decisions but cannot prove secure erasure.</p></div><div id="limitations" class="boundaries"></div></section>
    </div>
  </main>
  <footer><div>API __API_VERSION__. No browser storage, account, license proof, path, file, inventory, cleanup command, local result, or progress submission API is used.</div></footer>
  <script>
    const $=id=>document.getElementById(id);const state={payload:null,policy:"all",reviewed:new Set()};const value=input=>String(input??"");
    function add(parent,tag,text,className=""){const node=document.createElement(tag);node.textContent=value(text);if(className)node.className=className;parent.append(node);return node;}function setStatus(text,tone=""){$("status").textContent=text;$("status").className=`status ${tone}`;}function metric(label,text){const node=document.createElement("div");node.className="metric";add(node,"span",label);add(node,"strong",text);return node;}function visibleAreas(){const areas=state.payload?.areas||[];return state.policy==="all"?areas:areas.filter(item=>item.policy===state.policy);}function knownPracticeIds(){return new Set((state.payload?.practices||[]).map(item=>item.id));}
    function safeReceipt(){const known=knownPracticeIds();const reviewed=[...state.reviewed].filter(id=>known.has(id)).sort();return{schema_version:1,report_type:"VaultLink Privacy-Safe Browser Retention Review",generated_at_utc:new Date().toISOString(),api_version:state.payload.api_version,service_mode:state.payload.service_status.mode,signed_desktop_version:state.payload.signed_release.version||"",selected_policy:state.policy,reviewed_practice_ids:reviewed,reviewed_count:reviewed.length,practice_count:known.size,privacy_notice:"No name, contact, license proof, receipt, key, PIN, USB secret, path, filename, file content, local inventory, cleanup result, screenshot, process list, or free-form note is included."};}
    function renderMetrics(){const root=$("metrics");root.replaceChildren();const reviewed=[...state.reviewed].filter(id=>knownPracticeIds().has(id)).length;[["API",state.payload.api_version],["Service",state.payload.service_status.mode],["Signed desktop",state.payload.signed_release.version||"Not published"],["Areas",state.payload.area_count],["Practices",state.payload.practice_count],["Reviewed",`${reviewed} / ${state.payload.practice_count}`]].forEach(row=>root.append(metric(...row)));}
    function renderAreas(){const root=$("areas");root.replaceChildren();const items=visibleAreas();items.forEach(item=>{const card=document.createElement("article");card.className="area";add(card,"div",item.policy,"policy");add(card,"h3",item.label);add(card,"p",item.purpose);const facts=document.createElement("div");facts.className="facts";[["Retention",item.retention],["Customer control",item.customer_control]].forEach(([label,text])=>{const fact=document.createElement("div");fact.className="fact";add(fact,"strong",label);add(fact,"span",text);facts.append(fact);});card.append(facts);root.append(card);});setStatus(`${items.length} fixed retention area(s) visible. Browser receives no local storage result.`,"good");}
    function renderPractices(){const root=$("practices");root.replaceChildren();state.payload.practices.forEach(item=>{const card=document.createElement("article");card.className=`practice ${state.reviewed.has(item.id)?"reviewed":""}`;const box=document.createElement("input");box.type="checkbox";box.checked=state.reviewed.has(item.id);box.setAttribute("aria-label",`Review ${item.title}`);box.addEventListener("change",()=>{box.checked?state.reviewed.add(item.id):state.reviewed.delete(item.id);renderPractices();});const body=document.createElement("div");add(body,"div",item.category,"policy");add(body,"h3",item.title);add(body,"p",item.action);const fact=document.createElement("div");fact.className="fact";add(fact,"strong","Expected");add(fact,"span",item.expected);body.append(fact);card.append(box,body);root.append(card);});renderMetrics();}
    function render(data){state.payload=data;const select=$("policy");select.replaceChildren();[["all","All policies"],...data.policies.map(item=>[item.id,item.label])].forEach(([id,label])=>{const option=document.createElement("option");option.value=id;option.textContent=label;select.append(option);});select.disabled=false;["reset","next","visible","copy","print","export"].forEach(id=>$(id).disabled=false);const flow=$("flow");data.cleanup_flow.forEach((item,index)=>{const card=document.createElement("article");add(card,"div",`STEP ${index+1}`,"eyebrow");add(card,"h3",item.label);add(card,"p",item.detail);flow.append(card);});[["boundaries",data.privacy_boundaries,"BOUNDARY"],["limitations",data.limitations,"LIMITATION"]].forEach(([id,items,label])=>{const root=$(id);items.forEach((text,index)=>{const card=document.createElement("article");card.className="boundary";add(card,"div",`${label} ${index+1}`,"eyebrow");add(card,"p",text);root.append(card);});});$("workspace").hidden=false;renderAreas();renderPractices();}
    async function load(){try{const response=await fetch("/api/v1/retention-guide",{headers:{Accept:"application/json"},cache:"no-store",redirect:"error"});const data=await response.json();if(!response.ok)throw new Error(data.message||"Retention guide could not be loaded.");render(data);}catch(error){setStatus(error.message||"Retention guide could not be loaded.","bad");}}
    function reset(){state.reviewed.clear();renderPractices();}function reviewNext(){const item=state.payload.practices.find(entry=>!state.reviewed.has(entry.id));if(item)state.reviewed.add(item.id);renderPractices();}function reviewAll(){state.payload.practices.forEach(item=>state.reviewed.add(item.id));renderPractices();}async function copyPlan(){const report=safeReceipt();const lines=["VaultLink storage and retention review",`Reviewed fixed practices: ${report.reviewed_count}/${report.practice_count}`,`Policy view: ${report.selected_policy}`,`API: ${report.api_version} | Service: ${report.service_mode} | Signed desktop: ${report.signed_desktop_version||"not published"}`,report.privacy_notice];try{await navigator.clipboard.writeText(lines.join("\n"));setStatus("Privacy-safe retention review copied.","good");}catch(_error){setStatus("Clipboard access was blocked by the browser.","bad");}}function download(name,type,text){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}function exportJson(){download("vaultlink-browser-retention-review.json","application/json",JSON.stringify(safeReceipt(),null,2));setStatus("Privacy-safe browser retention review exported.","good");}
    $("policy").addEventListener("change",event=>{state.policy=event.target.value;renderAreas();});$("reset").addEventListener("click",reset);$("next").addEventListener("click",reviewNext);$("visible").addEventListener("click",reviewAll);$("copy").addEventListener("click",copyPlan);$("print").addEventListener("click",()=>window.print());$("export").addEventListener("click",exportJson);load();
  </script>
</body>
</html>"""
    return page.replace("__API_VERSION__", html.escape(str(api_version), quote=True))
